import React from 'react';
import { Box } from '@salesforce/retail-react-app/app/components/shared/ui';
import type { BoxProps } from '@chakra-ui/layout';

// Override of base responsive/index.jsx: base hardcodes Chakra's default `lg` (992px) as the
// mobile/desktop split. Zimmermann's own breakpoint system treats `md` (768px, gridSystem.ts,
// registered as theme.breakpoints.md) as that split everywhere else (header, footer, mega
// menu) — using `lg` here left a dead zone between 768-991px where content wrapped in both
// helpers was simultaneously hidden.
const MOBILE_DESKTOP_SPLIT = 'md';

type ResponsiveVisibilityProps = BoxProps & {
  children?: React.ReactNode;
};

export const HideOnDesktop = ({ children, ...rest }: ResponsiveVisibilityProps) => (
  <Box display={{ base: 'block', [MOBILE_DESKTOP_SPLIT]: 'none' }} {...rest}>
    {children}
  </Box>
);

export const HideOnMobile = ({ children, ...rest }: ResponsiveVisibilityProps) => (
  <Box display={{ base: 'none', [MOBILE_DESKTOP_SPLIT]: 'block' }} {...rest}>
    {children}
  </Box>
);

export default { HideOnMobile, HideOnDesktop };

